/**
 * Electrobun build config for the Twyne desktop shell.
 *
 * The desktop app is a thin native wrapper around the hosted web app at
 * https://twyne.love — SSR, Convex sync, Better Auth, and ATProto publishing
 * all run server-side, so the shell only needs a window pointed at the site.
 * There is no bundled `views://` frontend; the single Bun entrypoint
 * (`desktop/main.ts`) opens a BrowserWindow on the live URL.
 */
export default {
  app: {
    name: "Twyne",
    identifier: "love.twyne.desktop",
    version: "0.2.0",
    // Custom scheme reserved for ATProto OAuth deep-link callbacks (macOS).
    urlSchemes: ["twyne"],
  },
  runtime: {
    exitOnLastWindowClosed: true,
  },
  build: {
    bun: {
      entrypoint: "desktop/main.ts",
      define: {
        "process.env.TWYNE_DESKTOP_LOCAL_AI": JSON.stringify(
          localAiEnabled ? "true" : "false",
        ),
      },
    },
    copy: localAiEnabled ? localAiCopy : undefined,
    asarUnpack: localAiEnabled
      ? ["bin/**", "models/**", "*.node", "*.dll", "*.dylib", "*.so"]
      : undefined,
    mac: {
      defaultRenderer: "native",
      // Add `icons: "icon.iconset"` + a real .iconset before notarized
      // distribution; omitted so CI builds stay green without one.
    },
    linux: {
      defaultRenderer: "native",
    },
    win: {
      defaultRenderer: "native",
    },
  },
} satisfies ElectrobunConfig;

/**
 * Twyne desktop — Electrobun main (Bun) process.
 *
 * Opens a single native window on the hosted Twyne web app. Everything that
 * makes Twyne work (Qwik SSR, Convex sync, Better Auth passkeys, ATProto
 * publishing) is served from the deployed site, so the desktop build ships no
 * application code of its own — it is a branded, self-updating shell.
 *
 * If the build was produced with local AI enabled, a native LiteRT-LM server
 * (Gemma 4 E4B) is started on loopback and advertised to the page via URL
 * params, so the web app can route AI through the local model.
 *
 * Point the window at a local dev server by setting TWYNE_DESKTOP_URL, e.g.
 *   TWYNE_DESKTOP_URL=http://localhost:5173 bun start
 */
import { BrowserWindow } from "electrobun/bun";
import { startLocalAiServer } from "./litert-server";

const BASE_URL = process.env.TWYNE_DESKTOP_URL ?? "https://twyne.love";

function withParams(base: string, params: Record<string, string>): string {
  const u = new URL(base);
  u.searchParams.set("platform", "desktop");
  for (const [k, v] of Object.entries(params)) u.searchParams.set(k, v);
  return u.toString();
}

