  twyne folio update ID [--name NAME] [--type TYPE] [--file FILE] [--brief FILE] [--expected-updated-at MS]
  twyne folio search QUERY [--limit N]
  twyne folio import FILE... [--type TYPE]
  twyne folio export [ID...] [--format archive|markdown|html|txt] [--output FILE]
  twyne feedback get ID
  twyne citations list [--folio-id ID] [--search QUERY]
  twyne citations upsert --folio-id ID --file FILE

Credentials are read from TWYNE_API_URL + TWYNE_ACCESS_TOKEN first, then from
the chmod-0600 config written by auth login. Login prompts securely when a
token is not supplied, and also accepts one on stdin.
`;

function println(stream: Pick<NodeJS.WriteStream, "write">, value = ""): void {
  stream.write(`${value}\n`);
}

function json(io: CliIo, value: unknown): void {
  println(io.stdout, JSON.stringify(value, null, 2));
}

function required(value: string | undefined, label: string): string {
  if (!value?.trim()) throw new Error(`${label} is required`);
  return value.trim();
}

function parseNumber(
  value: string | undefined,
  label: string,
): number | undefined {
  if (value === undefined) return undefined;
  const parsed = Number(value);
  if (!Number.isFinite(parsed)) throw new Error(`${label} must be a number`);
  return parsed;
}

function parseType(value: string | undefined): FolioType | undefined {
  if (value === undefined) return undefined;
  if (value === "draft" || value === "notes" || value === "outline")
    return value;
  throw new Error("type must be draft, notes, or outline");
}

function parseIncludes(value: string | undefined): FolioInclude[] | undefined {
  if (value === undefined) return undefined;
  const includes = value
    .split(",")
    .map((entry) => entry.trim())
    .filter(Boolean);
  const allowed = new Set<string>(FOLIO_INCLUDES);
  const invalid = includes.filter((entry) => !allowed.has(entry));
  if (invalid.length)
    throw new Error(`Unknown include values: ${invalid.join(", ")}`);
  return includes as FolioInclude[];
}

function commandArgs<T extends ParseArgsOptionsConfig>(
  args: string[],
  options: T,
) {
  return parseArgs({
    args,
    options,
    allowPositionals: true,
    strict: true,
  } as const);
}

async function clientFrom(io: CliIo): Promise<TwyneClient> {
  return TwyneClient.fromCredentials(
    await loadCredentials(io.env, defaultConfigPath(io.env)),
  );
}

async function readJson(path: string): Promise<unknown> {
  try {
    return JSON.parse(await readFile(path, "utf8"));
  } catch (error) {
    if (error instanceof SyntaxError)
      throw new Error(`${path} is not valid JSON`);
    throw error;
  }
}

async function readStdin(): Promise<string> {
  const chunks: Buffer[] = [];
  for await (const chunk of process.stdin) chunks.push(Buffer.from(chunk));
  return Buffer.concat(chunks).toString("utf8").trim();
}

async function readAccessToken(io: CliIo): Promise<string> {
  if (!process.stdin.isTTY || typeof process.stdin.setRawMode !== "function") {
    return await readStdin();
  }
  const input = process.stdin;
  const wasRaw = input.isRaw;
  io.stdout.write("Twyne access token: ");
  return await new Promise<string>((resolve, reject) => {
    let value = "";
    const cleanup = () => {
      input.off("data", onData);
      input.setRawMode(wasRaw);
      input.pause();
      io.stdout.write("\n");
    };
    const onData = (chunk: Buffer | string) => {
      for (const character of String(chunk)) {
        if (character === "\u0003") {
          cleanup();
          reject(new Error("Login cancelled"));
          return;
        }
        if (character === "\r" || character === "\n") {
          cleanup();
          resolve(value.trim());
          return;
        }
        if (character === "\u007f" || character === "\b") {
          value = value.slice(0, -1);
        } else if (character >= " ") {
          value += character;
        }
      }
    };
    input.setRawMode(true);
    input.resume();
    input.on("data", onData);
  });
}

async function authCommand(args: string[], io: CliIo): Promise<void> {
  const action = args.shift();
  if (action === "login") {
    const parsed = commandArgs(args, {
      url: { type: "string" },
      token: { type: "string" },
    });
    const apiUrl = required(
      parsed.values.url ?? io.env.TWYNE_API_URL,
      "--url or TWYNE_API_URL",
    );
    const accessToken = required(
      parsed.values.token ??
        io.env.TWYNE_ACCESS_TOKEN ??
        (await readAccessToken(io)),
      "--token, TWYNE_ACCESS_TOKEN, or a token on stdin",
    );
    const client = new TwyneClient({ apiUrl, accessToken });
    await client.listFolios();
    const path = await writeConfig(
      { apiUrl, accessToken },
      defaultConfigPath(io.env),
    );
    println(
      io.stdout,
      `Authenticated with Twyne. Credentials saved to ${path} (mode 0600).`,
    );
    return;
  }
  if (action === "status") {
    commandArgs(args, {});
    const credentials = await loadCredentials(
      io.env,
      defaultConfigPath(io.env),
    );
    const folios = await TwyneClient.fromCredentials(credentials).listFolios();
    json(io, {
      authenticated: true,
      apiUrl: credentials.apiUrl,
      source: credentials.source,
      tokenPrefix: `${credentials.accessToken.slice(0, 18)}…`,
      folioCount: folios.length,
    });
    return;
  }
  if (action === "logout") {
    commandArgs(args, {});
    const path = defaultConfigPath(io.env);
    const removed = await deleteConfig(path);
    println(
      io.stdout,
      removed ? `Removed ${path}.` : `No saved Twyne config at ${path}.`,
    );
    if (io.env.TWYNE_API_URL || io.env.TWYNE_ACCESS_TOKEN) {
      println(
        io.stderr,
        "Environment credentials remain active; unset them to fully log out.",
      );
    }
    return;
  }
  throw new Error("Usage: twyne auth login|status|logout");
}

async function folioCommand(args: string[], io: CliIo): Promise<void> {
  const action = args.shift();
  if (action === "list") {
    const parsed = commandArgs(args, {
      json: { type: "boolean", default: false },
    });
    const folios = await (await clientFrom(io)).listFolios();
    if (parsed.values.json) return json(io, folios);
    if (!folios.length) return println(io.stdout, "No folios.");
    for (const folio of folios) {
      println(
        io.stdout,
        [
          folio.id ?? "-",
          folio.type ?? "draft",
          folio.updatedAt ?? "-",
          folio.name,
        ].join("\t"),
      );
    }
    return;
  }

  if (action === "get") {
    const parsed = commandArgs(args, { include: { type: "string" } });
    const folioId = required(parsed.positionals[0], "folio ID");
    if (parsed.positionals.length > 1)
      throw new Error("folio get accepts one ID");
    const bundle = await (
      await clientFrom(io)
    ).getFolio(folioId, parseIncludes(parsed.values.include));
    if (!bundle) throw new Error(`Folio not found: ${folioId}`);
    return json(io, bundle);
  }

  if (action === "create") {
    const parsed = commandArgs(args, {
      name: { type: "string" },
      type: { type: "string" },
      file: { type: "string" },
      brief: { type: "string" },
    });
    const file = parsed.values.file;
    const parsedFile = file
      ? parseImportSource({ name: file, content: await readFile(file, "utf8") })
          .folios[0]
      : undefined;
    const folio = await (
      await clientFrom(io)
    ).putFolio({
      folio: {
        name: required(parsed.values.name ?? parsedFile?.folio.name, "--name"),
        type:
          parseType(parsed.values.type) ?? parsedFile?.folio.type ?? "draft",
      },
      ...(parsedFile?.html !== undefined ? { html: parsedFile.html } : {}),
      ...(parsed.values.brief
        ? { brief: await readJson(parsed.values.brief) }
        : {}),
    });
    return json(io, folio);
  }

  if (action === "update") {
    const parsed = commandArgs(args, {
      name: { type: "string" },
      type: { type: "string" },
      file: { type: "string" },
      brief: { type: "string" },
      "expected-updated-at": { type: "string" },
    });
    const folioId = required(parsed.positionals[0], "folio ID");
    if (parsed.positionals.length > 1)
      throw new Error("folio update accepts one ID");
    const client = await clientFrom(io);
    const current = await client.getFolio(folioId, []);
    if (!current) throw new Error(`Folio not found: ${folioId}`);
    const file = parsed.values.file;
    const parsedFile = file
      ? parseImportSource({ name: file, content: await readFile(file, "utf8") })
          .folios[0]
      : undefined;
    const updated = await client.putFolio({
      folio: {
        ...current.folio,
        id: folioId,
        name: parsed.values.name ?? current.folio.name,
        type: parseType(parsed.values.type) ?? current.folio.type,
      },
      ...(parsedFile?.html !== undefined ? { html: parsedFile.html } : {}),
      ...(parsed.values.brief
        ? { brief: await readJson(parsed.values.brief) }
        : {}),
      ...(parsed.values["expected-updated-at"] !== undefined
        ? {
            expectedUpdatedAt: parseNumber(
              parsed.values["expected-updated-at"],
              "--expected-updated-at",
            ),
          }
        : {}),
    });
    return json(io, updated);
  }

  if (action === "search") {
    const parsed = commandArgs(args, { limit: { type: "string" } });
    const query = required(parsed.positionals.join(" "), "search query");
    const limit = parseNumber(parsed.values.limit, "--limit") ?? 20;
    return json(io, await (await clientFrom(io)).searchFolios(query, limit));
  }

  if (action === "import") {
    const parsed = commandArgs(args, { type: { type: "string" } });
    if (!parsed.positionals.length)
      throw new Error("folio import needs at least one file");
    const type = parseType(parsed.values.type);
    const sources: ImportSource[] = await Promise.all(
      parsed.positionals.map(async (name) => ({
        name,
        content: await readFile(name, "utf8"),
        type,
      })),
    );
    return json(io, await importSources(await clientFrom(io), sources));
  }

  if (action === "export") {
    const parsed = commandArgs(args, {
      format: { type: "string", default: "archive" },
      output: { type: "string" },
    });
    const format = parsed.values.format as ExportFormat;
    if (
      !(["archive", "markdown", "html", "txt"] as string[]).includes(format)
    ) {
      throw new Error("--format must be archive, markdown, html, or txt");
    }
    const artifact = exportBundles(
      await fetchFolioBundles(await clientFrom(io), parsed.positionals),
      format,
    );
    if (parsed.values.output) {
      await writeFile(parsed.values.output, artifact.content, "utf8");
      return json(io, {
        output: parsed.values.output,
        format: artifact.format,
        mimeType: artifact.mimeType,
      });
    }
    io.stdout.write(artifact.content);
    return;
  }

  throw new Error(
    "Usage: twyne folio list|get|create|update|search|import|export",
  );
}

async function feedbackCommand(args: string[], io: CliIo): Promise<void> {
  const action = args.shift();
  if (action !== "get") throw new Error("Usage: twyne feedback get ID");
  const parsed = commandArgs(args, {});
  const folioId = required(parsed.positionals[0], "folio ID");
  if (parsed.positionals.length > 1)
    throw new Error("feedback get accepts one ID");
  json(io, await (await clientFrom(io)).getFeedback(folioId));
}

function parseCitationEntries(value: unknown): CitationEntry[] {
  const entries = Array.isArray(value) ? value : [value];
  for (const [index, entry] of entries.entries()) {
    if (!entry || typeof entry !== "object" || Array.isArray(entry)) {
      throw new Error(`Citation ${index + 1} must be an object`);
    }
    if (typeof (entry as Record<string, unknown>).title !== "string") {
      throw new Error(`Citation ${index + 1} needs a title`);
    }
  }
  return entries as CitationEntry[];
}

async function citationsCommand(args: string[], io: CliIo): Promise<void> {
  const action = args.shift();
  if (action === "list") {
    const parsed = commandArgs(args, {
      "folio-id": { type: "string" },
      search: { type: "string" },
    });
    return json(
      io,
      await (
        await clientFrom(io)
      ).listCitations({
        ...(parsed.values["folio-id"]
          ? { folioId: parsed.values["folio-id"] }
          : {}),
        ...(parsed.values.search ? { search: parsed.values.search } : {}),
      }),
    );
  }
  if (action === "upsert") {
    const parsed = commandArgs(args, {
      "folio-id": { type: "string" },
      file: { type: "string" },
    });
    const folioId = required(parsed.values["folio-id"], "--folio-id");
    const path = required(parsed.values.file, "--file");
    return json(
      io,
      await (
        await clientFrom(io)
      ).putCitations(folioId, parseCitationEntries(await readJson(path))),
    );
  }
  throw new Error("Usage: twyne citations list|upsert");
}

export async function runCli(
  args = process.argv.slice(2),
  io: CliIo = DEFAULT_IO,
): Promise<number> {
  const command = args.shift();
  if (
    !command ||
    command === "help" ||
    command === "--help" ||
    command === "-h"
  ) {
    io.stdout.write(HELP);
    return 0;
  }
  try {
    if (command === "auth") await authCommand(args, io);
    else if (command === "folio") await folioCommand(args, io);
    else if (command === "feedback") await feedbackCommand(args, io);
    else if (command === "citations") await citationsCommand(args, io);
    else throw new Error(`Unknown command: ${command}`);
    return 0;
  } catch (error) {
    println(
      io.stderr,
      `Error: ${error instanceof Error ? error.message : String(error)}`,
    );
    return 1;
  }
}

if (
  process.argv[1] &&
  import.meta.url === pathToFileURL(process.argv[1]).href
) {
  process.exitCode = await runCli();
}
import { chmod, lstat, mkdir, readFile, rename, unlink, writeFile } from "node:fs/promises";
import { homedir } from "node:os";
import { dirname, join } from "node:path";

const CONFIG_VERSION = 1;

export interface TwyneConfig {
  version: 1;
  apiUrl: string;
  accessToken: string;
}

export interface Credentials {
  apiUrl: string;
  accessToken: string;
  source: "environment" | "config";
  configPath?: string;
}

export function defaultConfigPath(env: NodeJS.ProcessEnv = process.env): string {
  if (env.TWYNE_CONFIG_PATH?.trim()) return env.TWYNE_CONFIG_PATH.trim();
  const base = env.XDG_CONFIG_HOME?.trim() || join(homedir(), ".config");
  return join(base, "twyne", "config.json");
}

export function normalizeApiUrl(value: string): string {
  const trimmed = value.trim();
  if (!trimmed) throw new Error("Twyne API URL is required");
  let url: URL;
  try {
    url = new URL(trimmed);
  } catch {
    throw new Error(`Invalid Twyne API URL: ${trimmed}`);
  }
  if (url.protocol !== "https:" && url.protocol !== "http:") {
    throw new Error("Twyne API URL must use http or https");
  }
  return url.toString().replace(/\/$/, "");
}

function validateToken(value: string): string {
  const token = value.trim();
  if (!token.startsWith("twyne_pat_") || token.length <= "twyne_pat_".length) {
    throw new Error("Twyne access token must start with twyne_pat_");
  }
  return token;
}

function parseConfig(value: unknown): TwyneConfig {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new Error("Twyne config must be a JSON object");
  }
  const input = value as Record<string, unknown>;
  if (input.version !== CONFIG_VERSION) {
    throw new Error(`Unsupported Twyne config version: ${String(input.version)}`);
  }
  if (typeof input.apiUrl !== "string" || typeof input.accessToken !== "string") {
    throw new Error("Twyne config must contain apiUrl and accessToken");
  }
  return {
    version: CONFIG_VERSION,
    apiUrl: normalizeApiUrl(input.apiUrl),
    accessToken: validateToken(input.accessToken),
  };
}

async function assertSecureConfig(path: string): Promise<void> {
  const stat = await lstat(path);
  if (stat.isSymbolicLink()) {
    throw new Error(`Refusing to read symlinked Twyne config: ${path}`);
  }
  if (!stat.isFile()) throw new Error(`Twyne config is not a regular file: ${path}`);
  if (process.platform !== "win32" && (stat.mode & 0o077) !== 0) {
    throw new Error(
      `Twyne config permissions are too open (${(stat.mode & 0o777).toString(8)}); run chmod 600 ${path}`,
    );
  }
}

export async function readConfig(path = defaultConfigPath()): Promise<TwyneConfig> {
  await assertSecureConfig(path);
  let parsed: unknown;
  try {
    parsed = JSON.parse(await readFile(path, "utf8"));
  } catch (error) {
    if (error instanceof SyntaxError) throw new Error(`Twyne config is not valid JSON: ${path}`);
    throw error;
  }
  return parseConfig(parsed);
}

export async function loadCredentials(
  env: NodeJS.ProcessEnv = process.env,
  path = defaultConfigPath(env),
): Promise<Credentials> {
  const envUrl = env.TWYNE_API_URL?.trim();
  const envToken = env.TWYNE_ACCESS_TOKEN?.trim();
  if (envUrl || envToken) {
    if (!envUrl || !envToken) {
      throw new Error("Set both TWYNE_API_URL and TWYNE_ACCESS_TOKEN, or neither");
    }
    return {
      apiUrl: normalizeApiUrl(envUrl),
      accessToken: validateToken(envToken),
      source: "environment",
    };
  }
  try {
    const config = await readConfig(path);
    return { ...config, source: "config", configPath: path };
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") {
      throw new Error(
        "Twyne is not authenticated. Run `twyne auth login` or set TWYNE_API_URL and TWYNE_ACCESS_TOKEN.",
      );
    }
    throw error;
  }
}

export async function writeConfig(
  input: { apiUrl: string; accessToken: string },
  path = defaultConfigPath(),
): Promise<string> {
  const config: TwyneConfig = {
    version: CONFIG_VERSION,
    apiUrl: normalizeApiUrl(input.apiUrl),
    accessToken: validateToken(input.accessToken),
  };
  const directory = dirname(path);
  await mkdir(directory, { recursive: true, mode: 0o700 });
  if (process.platform !== "win32") await chmod(directory, 0o700);
  const temporary = join(directory, `.config-${process.pid}-${Date.now()}.tmp`);
  try {
    await writeFile(temporary, `${JSON.stringify(config, null, 2)}\n`, {
      encoding: "utf8",
      mode: 0o600,
      flag: "wx",
    });
    if (process.platform !== "win32") await chmod(temporary, 0o600);
    await rename(temporary, path);
    if (process.platform !== "win32") await chmod(path, 0o600);
  } catch (error) {
    await unlink(temporary).catch(() => undefined);
    throw error;
  }
  return path;
}

export async function deleteConfig(path = defaultConfigPath()): Promise<boolean> {
  try {
    await unlink(path);
    return true;
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return false;
    throw error;
  }
}
# Twyne tools

`@twyne/tools` provides two local, scriptable ways to work with a Twyne account:

- `twyne`, a CLI for authentication, folios, critiques, and citations.
- `twyne-mcp`, a stdio MCP server with exactly 10 focused tools.

Both clients use Twyne's authenticated `POST /api/integrations/v1` boundary. The access token belongs to the local user and is never sent anywhere except the configured Twyne URL.

## Install and authenticate

Requires Node.js 20 or newer.

```sh
npm install --global @twyne/tools
twyne auth login --url https://YOUR-TWYNE-DEPLOYMENT
```

Paste the personal access token at the hidden prompt, pass it with `--token`, set `TWYNE_ACCESS_TOKEN`, or pipe it on stdin. Login validates the token before saving it. The saved config lives at `$XDG_CONFIG_HOME/twyne/config.json` (normally `~/.config/twyne/config.json`) and is created with mode `0600`; its directory is mode `0700`. `TWYNE_CONFIG_PATH` can select another config file.

For ephemeral environments, skip the config file:

```sh
export TWYNE_API_URL=https://YOUR-TWYNE-DEPLOYMENT
export TWYNE_ACCESS_TOKEN=twyne_pat_...
twyne auth status
```

The environment variables must be supplied together and take precedence over the config file.

## CLI

```sh
# Folios
twyne folio list --json
twyne folio get FOLIO_ID
twyne folio create --name "New essay" --type draft --file opening.md
twyne folio update FOLIO_ID --file revision.html --expected-updated-at 1785780000000
twyne folio search "particular phrase" --limit 10

# Bulk exchange
twyne folio import notes.md chapter.html research.txt backup.twyne.json
twyne folio export --format archive --output all-writing.twyne.json
twyne folio export FOLIO_ID --format markdown --output essay.md

# Critiques and sources
twyne feedback get FOLIO_ID
twyne citations list --folio-id FOLIO_ID --search "author or DOI"
twyne citations upsert --folio-id FOLIO_ID --file citations.json
```

`citations.json` may contain one citation object or an array. A title is required. Supplying an existing `id` updates that citation; omitting it creates one.

## MCP

Point any stdio MCP client at the installed binary and provide credentials through the config or environment:

```json
{
  "mcpServers": {
    "twyne": {
      "command": "twyne-mcp",
      "env": {
        "TWYNE_API_URL": "https://YOUR-TWYNE-DEPLOYMENT",
        "TWYNE_ACCESS_TOKEN": "twyne_pat_..."
      }
    }
  }
}
```

The tool surface is deliberately small:

1. `twyne_list_folios`
2. `twyne_get_folio`
3. `twyne_create_folio`
4. `twyne_update_folio`
5. `twyne_search_folios`
6. `twyne_import_folios`
7. `twyne_export_folios`
8. `twyne_get_feedback`
9. `twyne_list_citations`
10. `twyne_upsert_citations`

Successful tools return the same data as both human-readable JSON text and MCP `structuredContent`. For a quick review loop, call `twyne_get_feedback`; it returns persona notes and replies, the rubric, and suggestions together. For grounded writing, call `twyne_list_citations` before research and `twyne_upsert_citations` after using a source so its provenance remains attached to the folio.

## Twyne archive v2

Bulk exchange uses a JSON envelope rather than a zip file, which lets MCP clients pass it without filesystem access:

```json
{
  "format": "twyne-archive",
  "version": 2,
  "exportedAt": "2026-08-03T12:00:00.000Z",
  "folios": [
    {
      "folio": { "id": "...", "name": "Essay", "type": "draft" },
      "html": "<p>Manuscript</p>",
      "brief": {},
      "feedback": {},
      "rubric": {},
      "suggestions": [],
      "citations": []
    }
  ]
}
```

HTML, brief, and citations can be imported through the integration API. Feedback, rubric results, and suggestions are exported for reference but are read-only, so importing an archive reports them as skipped rather than pretending they were restored.

## Development

```sh
bun test
bun run check
bun run build
```
export type FolioType = "draft" | "notes" | "outline";

export interface Folio {
  id?: string;
  name: string;
  type?: FolioType;
  createdAt?: number;
  updatedAt?: number;
  layout?: unknown;
  header?: string;
  footer?: string;
  [key: string]: unknown;
}

export const FOLIO_INCLUDES = [
  "content",
  "brief",
  "feedback",
  "rubric",
  "suggestions",
  "citations",
] as const;

export type FolioInclude = (typeof FOLIO_INCLUDES)[number];

export interface FolioBundle {
  folio: Folio;
  html?: string;
  contentUpdatedAt?: number | null;
  brief?: unknown;
  feedback?: unknown;
  rubric?: unknown;
  suggestions?: unknown[];
  citations?: CitationEntry[];
  [key: string]: unknown;
}

export interface CitationEntry {
  id?: string;
  title: string;
  folioId?: string;
  author?: string;
  url?: string;
  doi?: string;
  citationKey?: string;
  accessedAt?: number;
